//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn pi_domstring_raw_terminator_rejection_has_typed_error_and_no_identity_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var html=document.implementation.createHTMLDocument('owner'),xml=document.implementation.createDocument(null,''),generic=new Document(),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;var owners=[document,html,xml,generic,template];");let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);run(&mut doc,&mut forms,&mut page,r#"for(var owner of owners){var caught=false;try{owner.createProcessingInstruction('target','raw\ud800?>tail');}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught)throw 'raw data terminator must throw native InvalidCharacterError';}var caught=false;try{new ProcessingInstruction('target','raw\udfff?>');}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught)throw 'constructor raw data terminator';"#);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);
}
#[test]
fn pi_domstring_raw_target_converts_both_arguments_before_typed_name_validation(){
 let(mut doc,mut forms,mut page)=fixture();let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);run(&mut doc,&mut forms,&mut page,r#"var trace='',caught=false,target={toString:function(){trace+='target|';return '\ud800';}},data={toString:function(){trace+='data|';return 'held';}};try{document.createProcessingInstruction(target,data);}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught||trace!=='target|data|')throw 'DOMString conversion order before XML Name validation';trace='';caught=false;try{new ProcessingInstruction(target,data);}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught||trace!=='target|data|')throw 'constructor DOMString conversion order';"#);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);
}
#[test]
fn pi_domstring_valid_units_factory_defaults_owners_clones_and_legal_target_names(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var xml=document.implementation.createDocument(null,''),generic=new Document(),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,xml,generic,template]){var pi=owner.createProcessingInstruction('π:target','?\ud800>'),copy=pi.cloneNode(false);if(!(pi instanceof ProcessingInstruction)||!(pi instanceof CharacterData)||pi.nodeType!==7||pi.nodeName!=='π:target'||pi.target!=='π:target'||pi.data.length!==3||pi.data.charCodeAt(1)!==0xd800||pi.ownerDocument!==owner||pi.parentNode!==null||copy===pi||copy.target!==pi.target||copy.data!==pi.data||copy.ownerDocument!==owner)throw 'genuine PI scalar XML Name and exact data';var undefinedData=owner.createProcessingInstruction('xml',undefined);if(undefinedData.target!=='xml'||undefinedData.data!=='undefined')throw 'Document explicit undefined is a DOMString';}var ordinary=new ProcessingInstruction('target'),explicit=new ProcessingInstruction('target',undefined),pi=new ProcessingInstruction('target','raw\udfff');if(ordinary.data!==''||explicit.data!==''||pi.data.charCodeAt(3)!==0xdfff||pi.ownerDocument!==document)throw 'constructor optional data defaults and units';"#);
}
